"""Criteria for `auto-mutex-needs-tile-group`.

The criteria are “which line, which rule, and whether it was waived,” not the full message—the message can change, while
line number and rule name are the contract.
"""

from pathlib import Path

import pytest

from _checks import synchronisation

PREAMBLE = "import pypto_pro.language as pl\n\n\n"

TILE = "pl.TileType(shape=[8, 8], dtype=pl.DT_INT32, target_memory=pl.MemorySpace.Vec)"


def _write(
    tmp_path: Path,
    body: str,
    *,
    decorator: str = "@pl.jit(auto_mutex=True)",
    docstring: str = "",
) -> Path:
    doc = f'    """{docstring}\n    """\n' if docstring else ""
    text = PREAMBLE + f"{decorator}\ndef _kernel(x, out):\n" + doc + body
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    return path


BODY = 6
"""Line number of the first function-body line in the file generated by `_write` (one import line + two blank lines +
decorator + def).
Use `BODY + k` instead of a literal: miscounting blank lines caused every test in the first version of
`test_hardware.py` to fail."""


def _hits(path: Path) -> list[tuple[int, str, bool]]:
    return [
        (finding.lineno, finding.rule, finding.waived)
        for finding in synchronisation.check(path)
    ]


# ---------------------------------------------------------------------------
# Reported cases
# ---------------------------------------------------------------------------


def test_bare_make_tile_under_auto_mutex_is_reported(tmp_path):
    """The core case for this rule: the parsed IR contains no synchronization ops (see the comparison table in the
    module docstring).
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        f"    dst = pl.make_tile({TILE}, addr=0x0100)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n"
        "        pl.store(out, dst, [0, 0])\n",
    )
    assert _hits(path) == [
        (BODY, synchronisation.RULE, False),
        (BODY + 1, synchronisation.RULE, False),
    ]


def test_a_group_elsewhere_does_not_cover_the_bare_tile(tmp_path):
    """Still report when `make_tile_group` is present: a tile outside the group is not synchronized just because another
    tile joined it.
    """
    path = _write(
        tmp_path,
        f"    g = pl.make_tile_group(type={TILE}, addrs=[0x0000], mutex_ids=[0])\n"
        f"    scratch = pl.make_tile({TILE}, addr=0x0200)\n"
        "    with pl.section_vector():\n"
        "        pl.load(g.next(), x, [0, 0])\n",
    )
    assert _hits(path) == [(BODY + 1, synchronisation.RULE, False)]


def test_kernels_built_by_a_factory_are_checked(tmp_path):
    """Nested definitions must be checked too. **This was the first shape caught by the rule**: `dma_pad` has one kernel
    for each of four pad values, all inside a factory function; scanning only module-level definitions would miss all of
    them.
    """
    text = (
        PREAMBLE + "def _make(pad):\n"
        "    @pl.jit(auto_mutex=True)\n"
        "    def kernel(x, out):\n"
        f"        dst = pl.make_tile({TILE}, addr=0x0100)\n"
        "        with pl.section_vector():\n"
        "            pl.store(out, dst, [0, 0])\n"
        "    return kernel\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == [(7, synchronisation.RULE, False)]


# ---------------------------------------------------------------------------
# Non-reported cases: these determine whether the tool is a gate or a source of noise.
# ---------------------------------------------------------------------------


def test_a_tile_group_with_mutex_ids_passes(tmp_path):
    path = _write(
        tmp_path,
        f"    g = pl.make_tile_group(type={TILE}, addrs=[0x0000, 0x0100],"
        " mutex_ids=[0, 1])\n"
        "    with pl.section_vector():\n"
        "        pl.load(g.next(), x, [0, 0])\n",
    )
    assert _hits(path) == []


def test_manual_sync_silences_the_rule(tmp_path):
    """Manual synchronization shows that the author is handling synchronization, so this rule stays silent. It checks
    “relying on `auto_mutex`,” not “whether synchronization is sufficient” (that requires knowing which pipeline each op
    uses, a compile-time responsibility).
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n"
        "        pl.system.sync_src(set_pipe=pl.PipeType.MTE2,"
        " wait_pipe=pl.PipeType.V, event_id=0)\n"
        "        pl.system.sync_dst(set_pipe=pl.PipeType.MTE2,"
        " wait_pipe=pl.PipeType.V, event_id=0)\n",
    )
    assert _hits(path) == []


def test_bar_all_also_counts_as_manual_sync(tmp_path):
    """Match prefixes (`sync_` / `bar_` / `mutex_`) instead of enumerating names: missing a new member is worse than
    accepting one too many.
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n"
        "        pl.system.bar_all()\n",
    )
    assert _hits(path) == []


@pytest.mark.parametrize(
    "decorator", ["@pl.jit", "@pl.jit()", "@pl.jit(name='example')"]
)
def test_default_auto_mutex_is_checked(tmp_path, decorator):
    """The framework IR is the same when `auto_mutex` is omitted or explicitly set to True; bare tiles still have no
    locks.
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        decorator=decorator,
    )
    assert _hits(path) == [(BODY, synchronisation.RULE, False)]


def test_expanded_jit_options_are_not_assumed_to_use_the_default(tmp_path):
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0)\n",
        decorator="@pl.jit(**options)",
    )
    assert _hits(path) == []


def test_auto_mutex_from_a_variable_is_not_judged(tmp_path):
    """A variable expression cannot be judged statically. **Do not report it**: a “possible” violation would make this
    tool noisy.
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        decorator="@pl.jit(auto_mutex=FLAG)",
    )
    assert _hits(path) == []


def test_auto_mutex_false_is_not_this_rule(tmp_path):
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        decorator="@pl.jit(auto_mutex=False)",
    )
    assert _hits(path) == []


def test_a_kernel_without_tiles_passes(tmp_path):
    path = _write(tmp_path, "    with pl.section_vector():\n        pass\n")
    assert _hits(path) == []


# ---------------------------------------------------------------------------
# Counterexample declarations
# ---------------------------------------------------------------------------


def test_a_declared_counterexample_is_waived_but_still_printed(tmp_path):
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        docstring=f"反例：{synchronisation.RULE} —— 就是要展示不同步会怎样",
    )
    hits = _hits(path)
    assert hits == [(BODY + 2, synchronisation.RULE, True)], hits


def test_a_stale_declaration_is_itself_reported(tmp_path):
    """When the declaration remains but the violation is gone, **report the declaration itself**—a stale waiver could
    hide a real future violation.

    This test shares `source.apply_claim` with the `hardware` tests so waiver semantics have one definition.
    Report the `def` line (`BODY - 1`), not the decorator line.
    """
    path = _write(
        tmp_path,
        f"    g = pl.make_tile_group(type={TILE}, addrs=[0x0000], mutex_ids=[0])\n"
        "    with pl.section_vector():\n"
        "        pl.load(g.next(), x, [0, 0])\n",
        docstring=f"反例：{synchronisation.RULE} —— 声明留着但违规已经改掉了",
    )
    assert _hits(path) == [(BODY - 1, synchronisation.RULE, False)]
